export const createQueueDevice = async (queueDisplayDeviceInput: QueueDisplayDeviceInput, options?: RequestInit): Promise<QueueDisplayDevice> => {

  return customFetch<QueueDisplayDevice>(getCreateQueueDeviceUrl(),
  {
    ...options,
    method: 'POST',
    headers: { 'Content-Type': 'application/json', ...options?.headers },
    body: JSON.stringify(queueDisplayDeviceInput)
  }
);}




